{* Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/week-menu.json
    Meal delivery as a week: one column per day (its name and delivery note) with the meal of that day as a small card (picture, name, weight, price). Axes: media (image, none), tone.
    Props (p): id, title, lead, dishes, sections, empty, labels, media, tone, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_lead = ($p['lead'] ?? '')}
{var $v_dishes = ($p['dishes'] ?? null)}
{var $v_sections = ($p['sections'] ?? null)}
{var $v_empty = ($p['empty'] ?? '')}
{var $v_media = ($p['media'] ?? 'image')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $c_10}
  {if og_t(og_eq(og_len($v_sections), 0))}
    {=og_include('blocks/empty-state.latte', ['p' => ['icon' => 'calendar', 'title' => $v_empty]])|noescape}
  {else}
    {capture $c_9}
      {foreach og_l($v_sections) as $v_s}
        {capture $c_8}
          {capture $c_1}
            {=og_text(og_get($v_s, ['title']))}
          {/capture}
          {=og_include('compose/Text.latte', ['size' => 'sm', 'weight' => 'semibold', 'children' => (string) $c_1])|noescape}
          {capture $c_2}
            {=og_text(og_get($v_s, ['note']))}
          {/capture}
          {=og_include('compose/Text.latte', ['size' => 'xs', 'class' => 'text-muted-foreground', 'children' => (string) $c_2])|noescape}
          {foreach og_l($v_dishes) as $v_d}
            {if og_t(og_eq(og_get($v_d, ['tag']), og_get($v_s, ['key'])))}
              {capture $c_7}
                {if og_t(og_eq($v_media, 'image'))}
                  {=og_include('blocks/media-frame.latte', ['p' => ['alt' => og_get($v_d, ['name']), 'ratio' => '4/3']])|noescape}
                {/if}
                {capture $c_3}
                  {=og_text(og_get($v_d, ['name']))}
                {/capture}
                {=og_include('compose/Text.latte', ['size' => 'sm', 'weight' => 'semibold', 'children' => (string) $c_3])|noescape}
                {capture $c_6}
                  {capture $c_4}
                    {=og_text(og_get($v_d, ['weight']))}
                  {/capture}
                  {=og_include('compose/Text.latte', ['size' => 'xs', 'class' => 'text-muted-foreground', 'children' => (string) $c_4])|noescape}
                  {capture $c_5}
                    {=og_text(og_money(og_get($v_d, ['price']), og_get($v_d, ['currency'])))}
                  {/capture}
                  {=og_include('compose/Inline.latte', ['class' => 'text-sm font-bold', 'children' => (string) $c_5])|noescape}
                {/capture}
                {=og_include('compose/Group.latte', ['gap' => '2', 'align' => 'baseline', 'justify' => 'between', 'children' => (string) $c_6])|noescape}
              {/capture}
              {=og_include('compose/Stack.latte', ['gap' => '2', 'class' => 'rounded bg-card inset-ring inset-ring-border p-4', 'attrs' => og_attrs(['data-testid', 'item']), 'children' => (string) $c_7])|noescape}
            {/if}
          {/foreach}
        {/capture}
        {=og_include('compose/Stack.latte', ['gap' => '2', 'class' => 'border-t-2 border-primary pt-4', 'attrs' => og_attrs(['data-testid', 'day']), 'children' => (string) $c_8])|noescape}
      {/foreach}
    {/capture}
    {=og_include('compose/Box.latte', ['class' => 'grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-5', 'attrs' => og_attrs(['data-testid', 'items']), 'children' => (string) $c_9])|noescape}
  {/if}
{/capture}
{=og_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'lead' => $v_lead, 'tone' => $v_tone, 'landmarkLabel' => $v_landmarkLabel], 'children' => og_markup($c_10)])|noescape}
